KG42.register("rules-6470891861d96acc6568c38f",{"id":"47-electricity_hydrogen_market::v141-c-R009","paper":"47-electricity_hydrogen_market","record":{"rule_id":"v141-c-R009","mechanism_id":"v141-a-M01","name":"Local clearing price","process_stage":"pricing","market_meaning":"The iterative local market clearing process generates electricity prices to balance supply and demand. Scope: Electricity-price formation through iterative LEM clearing. The last accepted unit of the local allocation on the surplus curve supplies the unit price used as the LEM price. Scope: Electricity pricing from accepted local allocations when supply and demand curves do not intersect. Condition: The supply and demand curves fail to intersect. The LEM electricity price is bounded by the DisCo purchasing and selling electricity prices. Scope: Electricity-price bounds in the LEM. The LEM hydrogen price equals the hydrogen-station price minus the parameter µ^H, as specified by equation (31). Scope: Hydrogen pricing in the LEM.","independence_rationale":"Relations governed by the approved function pricing.local under the fixed relation-ownership template. Conditional branches retain their explicit scope in local constraints.","V":["clearing.local","pricing.local"],"E":[{"edge_id":"v141-c-R009-E001","source":"clearing.local","target":"pricing.local","type":"links","constraint_ids":["v141-c-R009-C001","v141-c-R009-C002"],"evidence_ids":["v141-b-g02-e07","v141-b-g02-e08","v141-b-g02-e14","v141-b-g02-e23"]}],"omega":{"market_type":"LEM","network_level":null,"jurisdiction":null,"pricing_scope":null,"time_scale":null,"participant_types":[],"trading_stage":"pricing","context_text":"Electricity pricing from accepted local allocations when supply and demand curves do not intersect. | Electricity-price bounds in the LEM. | Electricity-price formation through iterative LEM clearing. | Hydrogen pricing in the LEM.","unknown_fields":["network_level","jurisdiction","pricing_scope","time_scale","participant_types"],"evidence_ids":["v141-b-g02-e05","v141-b-g02-e07","v141-b-g02-e08","v141-b-g02-e14","v141-b-g02-e23","v141-b-g02-e24"]},"x":[{"variable_id":"v141-c-R009-x-lambda-L","symbol":"\\lambda_t^{L}","meaning":"LEM electricity price at time slot t.","kind":"operational","domain":"Time-indexed electricity price in the LEM, in €/kWh; the source does not state a separate numeric domain beyond the price bounds in C003.","unit":"€/kWh","indices":["t"],"evidence_ids":["v141-b-g02-e02","v141-b-g02-e23","v141-b-g02-e24"]},{"variable_id":"v141-c-R009-x-lambda-HL","symbol":"\\lambda_t^{HL}","meaning":"LEM hydrogen price at time slot t.","kind":"operational","domain":"Time-indexed hydrogen price in the LEM, in €/kg; its relation to the hydrogen-station price is given by source equation (31).","unit":"€/kg","indices":["t"],"evidence_ids":["v141-b-g02-e02","v141-b-g02-e05","v141-b-g02-e15"]}],"theta":[{"parameter_id":"v141-c-R009-theta-lambda-HS","symbol":"\\lambda_t^{HS}","meaning":"Hydrogen price from the hydrogen station (outside option) at time slot t.","value":{"kind":"unspecified","number_value":null,"text_value":null},"unit":"€/kg","indices":["t"],"evidence_ids":["v141-b-g02-e05","v141-b-g02-e11","v141-b-g02-e26"]},{"parameter_id":"v141-c-R009-theta-mu-H","symbol":"\\mu^H","meaning":"Price difference between the hydrogen-station price λ_t^{HS} and the LEM hydrogen price λ_t^{HL}, in €/kg.","value":{"kind":"unspecified","number_value":null,"text_value":null},"unit":"€/kg","indices":[],"evidence_ids":["v141-b-g02-e05","v141-b-g02-e11","v141-b-g02-e15"]},{"parameter_id":"v141-c-R009-theta-lambda-DP","symbol":"\\lambda_t^{DP}","meaning":"DisCo purchasing electricity price at time slot t.","value":{"kind":"unspecified","number_value":null,"text_value":null},"unit":"€/kWh","indices":["t"],"evidence_ids":["v141-b-g02-e24","v141-b-g02-e27"]},{"parameter_id":"v141-c-R009-theta-lambda-DS","symbol":"\\lambda_t^{DS}","meaning":"DisCo selling electricity price at time slot t.","value":{"kind":"unspecified","number_value":null,"text_value":null},"unit":"€/kWh","indices":["t"],"evidence_ids":["v141-b-g02-e24","v141-b-g02-e27"]}],"phi":[{"constraint_id":"v141-c-R009-C001","kind":"procedural","role":"core","statement":"The iterative local market clearing process generates electricity prices to balance supply and demand. Scope: Electricity-price formation through iterative LEM clearing.","expression":null,"formalization_origin":"not_formalized","template_id":null,"members":["clearing.local","pricing.local"],"variable_refs":[],"parameter_refs":[],"evidence_ids":["v141-b-g02-e07","v141-b-g02-e14","v141-b-g02-e23"]},{"constraint_id":"v141-c-R009-C002","kind":"procedural","role":"core","statement":"The last accepted unit of the local allocation on the surplus curve supplies the unit price used as the LEM price. Scope: Electricity pricing from accepted local allocations when supply and demand curves do not intersect. Condition: The supply and demand curves fail to intersect.","expression":null,"formalization_origin":"not_formalized","template_id":null,"members":["clearing.local","pricing.local"],"variable_refs":[],"parameter_refs":[],"evidence_ids":["v141-b-g02-e08"]},{"constraint_id":"v141-c-R009-C003","kind":"mathematical","role":"core","statement":"The LEM electricity price is bounded by the DisCo purchasing and selling electricity prices. Scope: Electricity-price bounds in the LEM.","expression":"\\lambda_t^{DP} \\le \\lambda_t^{L} \\le \\lambda_t^{DS}","formalization_origin":"equivalent_translation","template_id":null,"members":["pricing.local"],"variable_refs":["v141-c-R009-x-lambda-L"],"parameter_refs":["v141-c-R009-theta-lambda-DP","v141-c-R009-theta-lambda-DS"],"evidence_ids":["v141-b-g02-e24"]},{"constraint_id":"v141-c-R009-C004","kind":"mathematical","role":"core","statement":"The LEM hydrogen price equals the hydrogen-station price minus the parameter µ^H, as specified by equation (31). Scope: Hydrogen pricing in the LEM.","expression":"\\lambda_t^{HL} = \\lambda_t^{HS} - \\mu^H","formalization_origin":"source","template_id":null,"members":["pricing.local"],"variable_refs":["v141-c-R009-x-lambda-HL"],"parameter_refs":["v141-c-R009-theta-lambda-HS","v141-c-R009-theta-mu-H"],"evidence_ids":["v141-b-g02-e05"]}],"pi":[{"evidence_id":"v141-b-g02-e05","location":{"location_id":"src-3c8f4fd002-p05-c1r3__v141-a-M01-pricing","page":5,"printed_page":null,"section":"III. Mathematical Models for Players","anchor_text":"ρA,min ≤ρAt ≤ρA,max (24) P ρA ρA ρA,ini (25) th tT −1 = t0 = P tADP + P tALP ≤uAPt P AE L,max (26) P","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-05.png","occurrence_role":"condition"},"source_text":"\\lambda_t^{HL} = \\lambda_t^{HS} - \\mu^H (31). Equation (31) shows the relation between hydrogen price from the HS and in the LEM. According to (13)-(20), it is clear to see that when \\mu^H > 0 in (31), HVs will purchase hydrogen from the HSSA up to the maximum the HSSA can provide."},{"evidence_id":"v141-b-g02-e07","location":{"location_id":"src-3c8f4fd002-p05-c2r1__v141-a-M01-coordination","page":5,"printed_page":null,"section":"IV. Iterative LEM Clearing Method","anchor_text":"IEEE TRANSACTIONS ON POWER SYSTEMS, VOL. 33, NO. 4, JULY 2018 the IV. THE ITERATIVE LOCAL ENERGY MAR","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-05.png","occurrence_role":"definition"},"source_text":"As stated in Section II, the LEM clearing method is in an iterative manner. The players adjust their offering/bidding parameters after the LEM is cleared, and then the LEM is cleared again with adjusted parameters and broadcasts the results to players until no adjustment of players' offering/bidding parameters is observed. In each iteration process, the LEM clearing method should result in maximizing social welfare and it should respect the merit order principle."},{"evidence_id":"v141-b-g02-e08","location":{"location_id":"src-3c8f4fd002-p05-c2r1__v141-a-M01-pricing","page":5,"printed_page":null,"section":"IV. Iterative LEM Clearing Method","anchor_text":"IEEE TRANSACTIONS ON POWER SYSTEMS, VOL. 33, NO. 4, JULY 2018 the IV. THE ITERATIVE LOCAL ENERGY MAR","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-05.png","occurrence_role":"definition"},"source_text":"However, if the supply and demand curves fail to intersect, the LEM price will be settled as the price of the last unit of accepted amount on the curve that has a surplus [34]."},{"evidence_id":"v141-b-g02-e14","location":{"location_id":"src-3c8f4fd002-p06-c1r1__v141-a-M01-bidding","page":6,"printed_page":null,"section":"IV. Iterative LEM Clearing Method","anchor_text":"XIAO et al.: LOCAL ENERGY MARKET FOR ELECTRICITY AND HYDROGEN According to the iterative clearing me","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-06.png","occurrence_role":"formula"},"source_text":"According to the iterative clearing method, which will be described in Section IV-C, the HSSA only participates in the LEM after the LEM is cleared in the absence of the HSSA with \\lambda_t^{LnA,(r)} generated. Therefore, the offering/bidding parameters of the HSSA are \\lambda_t^{Aoffer,(r)} = \\lambda_t^{LnA,(r)}, if P_t^{Aoffer,(r)} \\in [0, P_t^{ALS,(r)}] (35); \\lambda_t^{Abid,(r)} = \\lambda_t^{LnA,(r)}, if P_t^{Abid,(r)} \\in [0, P_t^{ALP,(r)}] (36)."},{"evidence_id":"v141-b-g02-e23","location":{"location_id":"src-3c8f4fd002-p07-c2r1__v141-a-M01-pricing","page":7,"printed_page":null,"section":"IV. Iterative LEM Clearing Method","anchor_text":"IEEE TRANSACTIONS ON POWER SYSTEMS, VOL. 33, NO. 4, JULY 2018 r), In contrast, the electricity price","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-07.png","occurrence_role":"definition"},"source_text":"In contrast, the electricity prices are formed through an iteration process to balance supply and demand. As stated in the Step. 3 of the algorithm, the sequences of proposed bids for each consumer j generated by the algorithm are increasing, while the sequences of proposed offers for each producer i are decreasing. To be specific, in a time slot when the supplier finds out its offering amount is completely accepted, whereas there is still some bidding amount of the consumers left, the supplier will elevate its offering price intending to achieve higher utility. In this case, the price will rise consequently, and then the HSSA may increase its offering amount or reduce its bidding amount. As a result, the total supply increases or the total demand decreases, until the supplier no longer observes the complete acceptance of its offering amount or an increase in its utility. It is similar for the case when the consumer observes its bidding amount is completely accepted, whereas there is still some offering amount of the suppliers left. Moreover, as stated in Section IV-A, in the case where the supply and demand curves fail to intersect, the LEM price will be settled as the price of the last unit of accepted amount of the curve that has a surplus. Therefore, the price varies during the iteration process to balance the supply and demand, and will necessarily converge."},{"evidence_id":"v141-b-g02-e24","location":{"location_id":"src-3c8f4fd002-p07-c2r2__v141-a-M01-pricing","page":7,"printed_page":null,"section":"IV. Iterative LEM Clearing Method","anchor_text":"case, the price will rise consequently, and then the HSSA may ies increase its offering amount or re","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-07.png","occurrence_role":"definition"},"source_text":"On the other hand, players have the right to choose to trade with the DisCo or in the LEM, thus prices in the LEM will not exceed those of DisCo, i.e., in the range of \\lambda_t^{DP} and \\lambda_t^{DS}. This attribute introduces caps for the LEM prices."},{"evidence_id":"v141-b-g02-e02","location":{"location_id":"src-3c8f4fd002-p05-c1r2__v141-a-M01-bidding","page":5,"printed_page":null,"section":"III. Mathematical Models for Players","anchor_text":"For the HSSA, the objective function is sh th cu min CA = λDSt P tADP −λDPt P tADS + λLt P tALP of Γ","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-05.png","occurrence_role":"formula"},"source_text":"Q_t^{HAL} = \\sum_k Q_{k,t}^{HVL} (22)"},{"evidence_id":"v141-b-g02-e11","location":{"location_id":"src-3c8f4fd002-p05-c2r3__v141-a-M01-bidding","page":5,"printed_page":null,"section":"IV. Iterative LEM Clearing Method","anchor_text":", p y 24) P i,tDGdeal,(r−1) at the price of λL,(r−1)t in the r −1th iteration, then the offering par","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-05.png","occurrence_role":"formula"},"source_text":"\\lambda_{i,t}^{DGoffer,(r)} = \\lambda_t^{DP} \\text{ if } P_{i,t}^{DGoffer,(r)} \\in S_{i,t}^{DG1,(r)}; \\lambda_{i,t}^{DGoffer,(r)} = \\lambda_t^{L,(r-1)} \\text{ if } P_{i,t}^{DGoffer,(r)} \\in S_{i,t}^{DG2,(r)} (32) where S_{i,t}^{DG1,(r)} = [0, \\frac{1}{N_s}\\sum_s P_{i,t,s}^{DG} - P_{i,t}^{DGdeal,(r-1)}], S_{i,t}^{DG2,(r)} = [\\frac{1}{N_s}\\sum_s P_{i,t,s}^{DG} - P_{i,t}^{DGdeal,(r-1)}, \\frac{1}{N_s}\\sum_s P_{i,t,s}^{DG}]. Note that \\lambda_t^{L,(r-1)} > \\lambda_t^{DP}, otherwise the DG would not participate in the r-1th iteration of LEM."},{"evidence_id":"v141-b-g02-e15","location":{"location_id":"src-3c8f4fd002-p06-c1r2__v141-a-M01-coordination","page":6,"printed_page":null,"section":"IV. Iterative LEM Clearing Method","anchor_text":"C. The Iterative Clearing Procedure The HVs are the only consumers of hydrogen in the LEM, and their","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-06.png","occurrence_role":"condition"},"source_text":"The HVs are the only consumers of hydrogen in the LEM, and their trading strategies are quite easy to capture. According to (13)-(20) and (34), the HVs will purchase hydrogen from the LEM as much as they need or the LEM can supply, as long as the hydrogen price in the LEM is lower than that from the HS (\\mu^H > 0 in (31)). Since the HSSA is the unique hydrogen producer in the LEM, it is capable of settling the traded amount of hydrogen in the LEM by controlling the hydrogen price in the LEM according to (31). It is quite simple to observe that the HSSA would like to set \\mu^H in (31) to a positive value close to zero."},{"evidence_id":"v141-b-g02-e26","location":{"location_id":"src-3c8f4fd002-p07-c2r3__v141-a-M01-clearing","page":7,"printed_page":null,"section":"IV. Iterative LEM Clearing Method","anchor_text":"will The iterative LEM clearing procedure is a multiplayer game as in which all players only care ab","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-07.png","occurrence_role":"example"},"source_text":"In this section, the feasibility and effectiveness of the proposed iterative LEM clearing method are numerically analyzed in a 24-hr. period within a distribution network. The distribution network consists of renewable DGs with total capacity of 500 kW, 100 households with 90 EVs and 90 HVs, and an HSSA. Data regarding renewable DG generation are acquired from [2]. Note that there is no power generation before time slot 3 or after time slot 19. Data of three sorts of tasks of Loads are obtained from [35]-[36], with an assumption that the starting/ending time requirements of different tasks are in Gaussian distribution with a standard deviation of 1-3 hrs. For the detailed data of Loads, see Appendix. Driving patterns for EVs and HVs are randomly generated based on statistical data from the National Household Travel Survey (NHTS) data set in the U.S. [37]. All HVs are assumed to be Hyundai ix35 FUEL CELL vehicles, detailed parameters of which are illustrated in [38]. The HSSA is assumed to have 20 HSSs, the parameters of which are illustrated in [29]. To consider the uncertainties of renewable DG generation, demand of Loads and HVs, we generate 1000 scenarios and reduce them to 5 [39]. Prices for the DisCo are acquired from [9]. Hydrogen price from the HS is set to 1.35 €/kg. The adjustment of offering/bidding prices for DGs (\\epsilon_{i,t}^{DG}) and Loads (\\epsilon_{j,t}^{Load}) are all set to 0.001 €/kWh. To clearly illustrate the applicability and efficiency of the proposed LEM, as well as to address the influence of the HSS, three cases are compared. Case 1: Adopt LEM and HSSA exists in the LEM. Case 2: Not adopt LEM and players only trade with DisCo/HS. Case 3: Adopt LEM but no HSSA exists in the LEM. Note that to apply the mathematical models in Section III to Case 2, just set the quantity offered/bid in the LEM by each player as 0."},{"evidence_id":"v141-b-g02-e27","location":{"location_id":"src-3c8f4fd002-p08-c1r4__v141-a-M01-pricing","page":8,"printed_page":null,"section":"V. Case Study","anchor_text":"p g prices stay in the range of the purchasing and selling electricity prices of the DisCo. For time","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-08.png","occurrence_role":"example"},"source_text":"The market prices for Case 1 are shown in Fig. 4. The LEM prices stay in the range of the purchasing and selling electricity prices of the DisCo. For time plots when the LEM price equals the purchasing price of the DisCo, bids in the LEM are completely accepted, whereas offers are not. For time plots when the LEM price equals the selling price of the DisCo, offers in the LEM are completely accepted, whereas bids are not. For time plots when the LEM price lies between the purchasing and selling prices of the DisCo, neither offers nor bids are completely accepted."}],"field_notes":{"empty_E_reason":null,"empty_x_reason":null,"empty_theta_reason":null},"evidence_basis":"explicit","implementation_status":"unimplemented","status":"needs_review","lead_ids":["v141-a-M01-bidding","v141-a-M01-clearing","v141-a-M01-coordination","v141-a-M01-pricing","v141-a-M01-validation"],"extras":{"decision_anchor":"pricing.local","graph_fact_supports":[[{"evidence_id":"v141-b-g02-e23","quote":"In contrast, the electricity prices are formed through an iteration process to balance supply and demand."},{"evidence_id":"v141-b-g02-e07","quote":"As stated in Section II, the LEM clearing method is in an iterative manner."},{"evidence_id":"v141-b-g02-e14","quote":"the LEM is cleared in the absence of the HSSA with \\lambda_t^{LnA,(r)} generated."}],[{"evidence_id":"v141-b-g02-e08","quote":"However, if the supply and demand curves fail to intersect, the LEM price will be settled as the price of the last unit of accepted amount on the curve that has a surplus [34]."}],[{"evidence_id":"v141-b-g02-e24","quote":"prices in the LEM will not exceed those of DisCo, i.e., in the range of \\lambda_t^{DP} and \\lambda_t^{DS}. This attribute introduces caps for the LEM prices."}],[{"evidence_id":"v141-b-g02-e05","quote":"\\lambda_t^{HL} = \\lambda_t^{HS} - \\mu^H (31)."}]],"C2_formalization":{"graph_sha256":"4057328bfc3750ee6902994eebc31027f4953daa3df11575849787f4aa9ba9e2","applicability":"formalized","reason":"Partial formalization: source equation (31) gives an explicit LEM hydrogen-price relation, and the source-stated DisCo price caps support an explicit LEM electricity-price bound. The iterative price-formation description and the non-intersecting supply-demand-curve fallback remain procedural/not formalized because the supplied source quotations do not define curve objects or a last-accepted-unit formula. B evidence remains unreviewed.","bindings":[{"object_id":"v141-c-R009-x-lambda-L","node_ids":["pricing.local"],"edge_ids":["v141-c-R009-E001"],"rationale":"The LEM electricity price is a pricing.local outcome formed through iterative clearing.local clearing; frozen edge E001 links clearing.local to pricing.local and its C001/C002 evidence covers electricity-price formation."},{"object_id":"v141-c-R009-x-lambda-HL","node_ids":["pricing.local"],"edge_ids":[],"rationale":"The LEM hydrogen price belongs to pricing.local and is defined by source equation (31); no frozen clearing-pricing edge is specifically required for the hydrogen-price relation."},{"object_id":"v141-c-R009-theta-lambda-HS","node_ids":["pricing.local"],"edge_ids":[],"rationale":"The hydrogen-station price is an outside-option input to the pricing.local relation in equation (31), not a price produced by LEM clearing."},{"object_id":"v141-c-R009-theta-mu-H","node_ids":["pricing.local"],"edge_ids":[],"rationale":"μ^H is the source-defined price-spread parameter used in the pricing.local hydrogen-price equation (31)."},{"object_id":"v141-c-R009-theta-lambda-DP","node_ids":["pricing.local"],"edge_ids":[],"rationale":"The DisCo purchasing price is an outside-option parameter that supplies the lower bound in the pricing.local LEM electricity-price bound C003."},{"object_id":"v141-c-R009-theta-lambda-DS","node_ids":["pricing.local"],"edge_ids":[],"rationale":"The DisCo selling price is an outside-option parameter that supplies the upper bound in the pricing.local LEM electricity-price bound C003."},{"object_id":"v141-c-R009-C001","node_ids":["clearing.local","pricing.local"],"edge_ids":["v141-c-R009-E001"],"rationale":"C001 is a procedural statement spanning clearing.local and pricing.local; frozen edge E001 links local clearing to local pricing and lists C001."},{"object_id":"v141-c-R009-C002","node_ids":["clearing.local","pricing.local"],"edge_ids":["v141-c-R009-E001"],"rationale":"C002 is a procedural surplus-curve pricing fallback attached to the clearing-to-pricing link E001. It remains not_formalized because the supplied source text does not define supply/demand curves or a last-accepted-unit expression."},{"object_id":"v141-c-R009-C003","node_ids":["pricing.local"],"edge_ids":[],"rationale":"C003 formalizes the source statement that LEM prices lie in the range of the DisCo purchasing and selling prices, here translated as the equivalent inequality using λ_t^{DP} as lower bound and λ_t^{DS} as upper bound; source evidence e24 states the LEM price range and caps."},{"object_id":"v141-c-R009-C004","node_ids":["pricing.local"],"edge_ids":[],"rationale":"C004 faithfully transcribes source equation (31): the LEM hydrogen price equals the hydrogen-station price minus μ^H."}],"revision_requests":[]}},"quarantined_references":[]}});
